import numpy as np
L=open('answer.xyz').read().split('\n')
n=int(L[0]); P=np.array([[float(x) for x in l.split()[1:4]] for l in L[2:2+n]])
S=[l.split()[0] for l in L[2:2+n]]
r={'H':0.32,'C':0.77,'N':0.72,'O':0.70,'F':0.64,'Ir':1.5}
bonds={i:[] for i in range(n)}
for i in range(n):
  for j in range(i+1,n):
    d=np.linalg.norm(P[i]-P[j])
    if d< (r[S[i]]+r[S[j]])*1.3: bonds[i].append(j); bonds[j].append(i)
for i in range(n):
  print(i,S[i],[(j,S[j]) for j in bonds[i]])
"
